    "chapter": "1",
    "section": "1.6 工具的使用",
    "question": "工作中离开工作场所、暂停作业或遇到临时停电应立即____电动工具的电源。装卸钻头应在断电的情况下进行，严禁____进行钻孔。",
    "answer": "切断；手持工件",
    "blanks": 2,
    "full": "工作中离开工作场所、暂停作业或遇到临时停电应立即切断电动工具的电源。装卸钻头应在断电的情况下进行，严禁手持工件进行钻孔。",
