    "chapter": "1",
    "section": "1.6 工具的使用",
    "question": "行灯电压不应超过____。金属容器内、潮湿环境下、有爆炸危险的煤粉仓及沟道内、脱硫烟道等处工作时应使用____的安全电压。行灯变压器的外壳应可靠接地，不准使用自耦变压器。",
    "answer": "36V；12V",
    "blanks": 2,
    "full": "行灯电压不应超过36V。金属容器内、潮湿环境下、有爆炸危险的煤粉仓及沟道内、脱硫烟道等处工作时应使用12V的安全电压。行灯变压器的外壳应可靠接地，不准使用自耦变压器。",
    "ref": "1.6.6.1"
