    "question": "凡在热力、机械和热控设备、系统上进行安装、检修、维护或试验的工作，需要对设备采取安全措施的或需要运行人员在运行方式、操作调整上采取保障人身、设备运行安全措施的，必须填用____或____（格式见附录B、C）。",
