    "chapter": "3",
    "section": "3.2 厂内铁道",
    "question": "____车卸煤作业需____进行，并不得从车下面的门进入车内，观察存煤是否卸净必须从车厢的顶部查看。",
    "answer": "底开门；两人以上",
