    "sourceId": 170,
    "chapter": "3",
    "section": "3.2 汽车运输",
    "question": "运煤汽车司机在____过程中____开动车辆，只有得到卸煤人员已全部撤离的通知，鸣号示警，并确认车辆周围无人后方可开动车辆。",
    "answer": "人工卸煤；不得",
