    "full": "允许进入码头的人员、机动车辆及靠泊煤船均应遵守本规程。严禁人员在卸船机及抓斗行经路线逗留，机动车辆必须慢速行驶并不得任意停放，确保消防车辆进入码头的道路畅通。",
