    "section": "3.2 卸煤码头",
    "question": "卸煤码头属于重点防火区域，____保持清洁、整齐，各种油污、垃圾应及时清除，____堆放杂物及易燃、易爆物品。",
    "answer": "必须；严禁",
    "blanks": 2,
    "full": "卸煤码头属于重点防火区域，必须保持清洁、整齐，各种油污、垃圾应及时清除，严禁堆放杂物及易燃、易爆物品。",
