    "section": "3.2 卸煤码头",
    "question": "系缆工____在煤船上工作人员的指挥下，按照规定进行系、解缆工作，并严格执行系、解缆的先后顺序。系缆后任何人员____在缆桩附近逗留。",
    "answer": "必须；不得",
    "blanks": 2,
