    "chapter": "3",
    "section": "3.3 煤车清扫与煤船清舱",
    "question": "(4)____清舱机与卸煤机在同一舱口内同时工作。(5)清舱阶段卸煤机与清仓机交替工作时，当清舱机停止工作后，应尽量远离残煤堆停放。清舱指挥员____向卸煤机司机指明清舱机所停放的位置，卸煤机司机确认无误后方可操作卸煤。",
    "answer": "严禁；必须",
    "blanks": 2,
    "full": "(4)严禁清舱机与卸煤机在同一舱口内同时工作。(5)清舱阶段卸煤机与清仓机交替工作时，当清舱机停止工作后，应尽量远离残煤堆停放。清舱指挥员必须向卸煤机司机指明清舱机所停放的位置，卸煤机司机确认无误后方可操作卸煤。",
    "ref": "3.3.2.7"
