    "sourceId": 225,
    "chapter": "4",
    "section": "4.5 燃气轮机及其系统",
    "question": "燃气系统及其附近进行明火作业或做可能产生火花的工作均为动火作业。燃机及燃气区域（____）动火必须办理____措施票，上述区域周围30米内动火需办理动火措施票。",
    "answer": "燃气设备及管道10米内；一级动火",
