    "section": "4.5 燃气轮机及其系统",
    "question": "厂内燃气调压站、燃气前置模块区域应设置不低于2米的围墙或非燃烧材料栅栏，包括燃料模块等处应张贴“____”“____”等明显的警示牌和相应管理规定标志牌，入口处设置存放火种箱和静电释放装置。",
    "answer": "重点防火区域；严禁烟火",
    "blanks": 2,
    "full": "厂内燃气调压站、燃气前置模块区域应设置不低于2米的围墙或非燃烧材料栅栏，包括燃料模块等处应张贴“重点防火区域”“严禁烟火”等明显的警示牌和相应管理规定标志牌，入口处设置存放火种箱和静电释放装置。",
