    "chapter": "4",
    "section": "4.5 燃气轮机及其系统",
    "question": "燃气区域应按《石油____工程设计防火规范》（____）配备足够的消防设施、器材，并按时检查和试验，使其处于正常完好的备用状态。禁止将消防设施、安全标志移作他用。",
