    "chapter": "4",
    "section": "4.5 燃气轮机及其系统",
    "question": "机动车辆____进入燃气区域内（____）。因工作需要必须进入的机动车，应按规定在尾气排放处加装防火罩，并经相关部门批准后，在相关人员的监护下方可入内。",
