    "chapter": "A",
    "section": "A.2 触电急救",
    "question": "触电伤员____后，应将伤员扶卧在自己的____上（或在适当地方躺平），并注意保持伤员气道通畅。然后根据伤员的意识、呼吸及颈动脉搏动情况进行急救。",
    "answer": "脱离电源；安全带",
