    "chapter": "A",
    "section": "A.2 触电急救",
    "question": "____伤员送至地面后，应立即按照“A2.3伤员____后的处理”进行紧急抢救，直至专业医护人员接替救护为止。图A8杆上或高处触电下放方法图A9铁塔触电伤员营救方法。",
    "answer": "触电；脱离电源",
