    "chapter": "15",
    "section": "15.3 气割（焊）",
    "question": "用汽车运输气瓶时，气瓶不准顺____纵向放置，应____。气瓶押运人员应坐在司机驾驶室内，不准坐在车厢内。",
    "answer": "车厢；横向放置",
