    "sourceId": 445,
    "chapter": "15",
    "section": "15.5 热处理",
    "question": "设备、管道____作业时，应严格按热处理工艺进行，并密切监控温度升高情况，加热温度不应超出规范允许范围。检查时应采取____措施。",
