    "sourceId": 448,
    "chapter": "16",
    "section": "16.1 基本规定",
    "question": "____工作面四周应有____高的护栏，升降机构牢固完好，升降灵活，液压机构无渗漏现象，有明显的荷重标志，严禁超载使用，禁止在不平整的地面上使用。",
    "answer": "移动平台；1.2m",
