    "sourceId": 461,
    "chapter": "A",
    "section": "A.2 触电急救",
    "question": "对需要进行____的伤员，将其置于平地或硬板上，解开伤员领扣和____，去除或剪开限制呼吸的胸腹部紧身衣物，立即就地迅速进行有效心肺复苏抢救。",
