    "chapter": "15",
    "section": "15.3 气割（焊）",
    "question": "运输气瓶时应安放在特制半圆形的承窝木架内。如没有承窝木架时，可以在每一气瓶上套以厚度不小于____的____或橡皮圈两个，以免互相撞击。",
