    "question": "自动体外除颤仪（automatedexternaldefibrillator,____）的应用。AED已成为院前急救的重要组成，可以提高院前急救的成功率，当可以立即取得AED时，对于有目击的成人心脏骤停，应尽快使用AED除颤。若成人在未受监控的情况下发生心脏骤停，或不能立即取得AED，应在他人前往获取及准备AED时开始____。",
