    "section": "A.3 创伤急救",
    "question": "通常采用担架或徒手搬运伤员。正确的搬运可减少伤员痛苦，避免继发或加重伤。平地搬运时____，上下楼梯时____。昏迷的伤员，应将头偏向一侧，以保持呼吸道畅通。",
