    "question": "酸碱或有毒有害物品化学灼伤时，首先用干布或吸水性强的纸张清除残留化学品，迅速剪除被侵蚀的衣物，然后立即用大量____彻底冲洗，冲洗时间一般不少于____。救护者最好佩戴防护手套或其他防护用品进行操作，以免自身灼伤。",
