    "section": "A.3 创伤急救",
    "question": "在低温寒冷环境作业，或短时间接触介质（制冷剂、液态气体等），出现受冻部位皮肤苍白、温度低、麻木刺痛等冻结表现，排除其他原因所致的类似疾病，即可确定____。职业性冻伤的处置原则参见____。",
